<template><div><el-form-item label="实时模式"><el-select :model-value="modelValue" @update:model-value="$emit('update:modelValue',$event)"><el-option v-for="x in ['NATIVE','CASCADE','AUTO']" :key="x" :value="x" :label="x"/></el-select></el-form-item><el-alert :closable="false" :title="requirements"/></div></template><script setup lang="ts">import{computed}from'vue';const p=defineProps<{modelValue:string}>();defineEmits(['update:modelValue']);const requirements=computed(()=>p.modelValue==='NATIVE'?'需要 Realtime 模型':p.modelValue==='CASCADE'?'需要 ASR + Chat + TTS':'需要 Realtime 与 ASR + Chat + TTS 两条路径')</script>